import{_ as e,o,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_01_memory.png",r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_02_mcp.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_03_skills.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_04_plugins.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_05_hooks.png",h="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_06_subagents.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_07_growth.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_08_lifecycle.png",x=JSON.parse('{"title":"给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解","description":"Codex 的扩展体系看起来名词很多，但每一层解决的问题不同：AGENTS.md 记录项目规则，Memory 保存跨任务经验，Skill 封装工作流，MCP 连接工具与数据，Plugin 负责打包分发，Hook 在生命周期节点执行机械检查，Subagent 用隔离上下文并行处理独立任务。","frontmatter":{"title":"给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解","description":"Codex 的扩展体系看起来名词很多，但每一层解决的问题不同：AGENTS.md 记录项目规则，Memory 保存跨任务经验，Skill 封装工作流，MCP 连接工具与数据，Plugin 负责打包分发，Hook 在生命周期节点执行机械检查，Subagent 用隔离上下文并行处理独立任务。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":5,"source":"2026-08-10/ai_codex_official_07_customization_extensions.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_07_01_memory.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解"}],["meta",{"property":"og:description","content":"Codex 的扩展体系看起来名词很多，但每一层解决的问题不同：AGENTS.md 记录项目规则，Memory 保存跨任务经验，Skill 封装工作流，MCP 连接工具与数据，Plugin 负责打包分发，Hook 在生命周期节点执行机械检查，Subagent 用隔离上下文并行处理独立任务。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_01_memory.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解"}],["meta",{"name":"twitter:description","content":"Codex 的扩展体系看起来名词很多，但每一层解决的问题不同：AGENTS.md 记录项目规则，Memory 保存跨任务经验，Skill 封装工作流，MCP 连接工具与数据，Plugin 负责打包分发，Hook 在生命周期节点执行机械检查，Subagent 用隔离上下文并行处理独立任务。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_07_01_memory.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-07-customization-extensions.md","filePath":"archive/ai-codex-official-07-customization-extensions.md","lastUpdated":null}'),_={name:"archive/ai-codex-official-07-customization-extensions.md"};function m(u,a,k,g,f,b){return o(),t("div",null,[...a[0]||(a[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="给-codex-装上专业能力-mcp、skills、plugins、hooks-与多代理全解" tabindex="-1">给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解 <a class="header-anchor" href="#给-codex-装上专业能力-mcp、skills、plugins、hooks-与多代理全解" aria-label="Permalink to &quot;给 Codex 装上专业能力：MCP、Skills、Plugins、Hooks 与多代理全解&quot;">​</a></h1><p>Codex 的扩展体系看起来名词很多，但每一层解决的问题不同：<code>AGENTS.md</code> 记录项目规则，Memory 保存跨任务经验，Skill 封装工作流，MCP 连接工具与数据，Plugin 负责打包分发，Hook 在生命周期节点执行机械检查，Subagent 用隔离上下文并行处理独立任务。</p><h2 id="一、先按信息寿命选择承载层" tabindex="-1">一、先按信息寿命选择承载层 <a class="header-anchor" href="#一、先按信息寿命选择承载层" aria-label="Permalink to &quot;一、先按信息寿命选择承载层&quot;">​</a></h2><h3 id="_1-1-prompt-保存一次性要求" tabindex="-1">1.1 Prompt 保存一次性要求 <a class="header-anchor" href="#_1-1-prompt-保存一次性要求" aria-label="Permalink to &quot;1.1 Prompt 保存一次性要求&quot;">​</a></h3><p>当前目标、临时范围和本次特殊输出只在当前 Thread 有效，不需要永久写入项目。</p><h3 id="_1-2-agents-md-保存仓库规则" tabindex="-1">1.2 AGENTS.md 保存仓库规则 <a class="header-anchor" href="#_1-2-agents-md-保存仓库规则" aria-label="Permalink to &quot;1.2 AGENTS.md 保存仓库规则&quot;">​</a></h3><p>构建、测试、目录边界、工程规范和完成标准由团队版本化维护。它是显式指令，不是自动推断的记忆。</p><h3 id="_1-3-memory-保存可复用经验" tabindex="-1">1.3 Memory 保存可复用经验 <a class="header-anchor" href="#_1-3-memory-保存可复用经验" aria-label="Permalink to &quot;1.3 Memory 保存可复用经验&quot;">​</a></h3><p>Memory 适合跨任务保留用户偏好、稳定上下文和历史经验，但任何会变化的事实都应在使用前重新验证。敏感值和未经确认的推断不应长期保存。</p><p><img src="'+l+'" alt="图 1：当前 Prompt、项目规则与长期记忆的时间尺度"></p><h2 id="二、mcp-连接外部工具与数据" tabindex="-1">二、MCP 连接外部工具与数据 <a class="header-anchor" href="#二、mcp-连接外部工具与数据" aria-label="Permalink to &quot;二、MCP 连接外部工具与数据&quot;">​</a></h2><h3 id="_2-1-mcp-是协议边界" tabindex="-1">2.1 MCP 是协议边界 <a class="header-anchor" href="#_2-1-mcp-是协议边界" aria-label="Permalink to &quot;2.1 MCP 是协议边界&quot;">​</a></h3><p>它允许 Codex 发现并调用外部工具、读取资源或使用服务提供的能力。MCP 解决“怎样连接”，不自动解决数据质量、身份、权限和审计。</p><h3 id="_2-2-工具描述决定代理怎样调用" tabindex="-1">2.2 工具描述决定代理怎样调用 <a class="header-anchor" href="#_2-2-工具描述决定代理怎样调用" aria-label="Permalink to &quot;2.2 工具描述决定代理怎样调用&quot;">​</a></h3><p>清晰名称、参数 Schema、返回结果和副作用标记能减少误用。破坏性工具必须显式标注，并进入审批链。</p><h3 id="_2-3-接入前先画数据流" tabindex="-1">2.3 接入前先画数据流 <a class="header-anchor" href="#_2-3-接入前先画数据流" aria-label="Permalink to &quot;2.3 接入前先画数据流&quot;">​</a></h3><p>明确请求会带出哪些上下文、服务能访问什么、结果保存在哪里、失败如何处理。远程 MCP 和本地 STDIO Server 的信任面不同。</p><p><img src="'+r+'" alt="图 2：Codex 通过 MCP 连接工具、资源与外部服务"></p><h2 id="三、skill-把重复经验封装成流程" tabindex="-1">三、Skill 把重复经验封装成流程 <a class="header-anchor" href="#三、skill-把重复经验封装成流程" aria-label="Permalink to &quot;三、Skill 把重复经验封装成流程&quot;">​</a></h2><h3 id="_3-1-skill-适合重复且边界稳定的任务" tabindex="-1">3.1 Skill 适合重复且边界稳定的任务 <a class="header-anchor" href="#_3-1-skill-适合重复且边界稳定的任务" aria-label="Permalink to &quot;3.1 Skill 适合重复且边界稳定的任务&quot;">​</a></h3><p>源码审查、发布检查、固定格式报告和特定调试流程，都可以用 <code>SKILL.md</code> 描述触发条件、步骤、资源与验证。</p><h3 id="_3-2-渐进式披露控制上下文成本" tabindex="-1">3.2 渐进式披露控制上下文成本 <a class="header-anchor" href="#_3-2-渐进式披露控制上下文成本" aria-label="Permalink to &quot;3.2 渐进式披露控制上下文成本&quot;">​</a></h3><p>代理先看到能力摘要，确认匹配后再读取完整说明，只有需要时才加载参考和脚本。这样能力库可以增长，而不必把全部内容塞入每次会话。</p><h3 id="_3-3-skill-必须拥有完成证据" tabindex="-1">3.3 Skill 必须拥有完成证据 <a class="header-anchor" href="#_3-3-skill-必须拥有完成证据" aria-label="Permalink to &quot;3.3 Skill 必须拥有完成证据&quot;">​</a></h3><p>只有指导语而没有检查方法的 Skill，容易把错误流程稳定复用。可靠 Skill 应说明输入、产物、失败条件和验证。</p><p><img src="'+s+'" alt="图 3：Skill 从发现、加载到脚本与验证的渐进式披露"></p><h2 id="四、plugin-是能力分发单元" tabindex="-1">四、Plugin 是能力分发单元 <a class="header-anchor" href="#四、plugin-是能力分发单元" aria-label="Permalink to &quot;四、Plugin 是能力分发单元&quot;">​</a></h2><h3 id="_4-1-一个-plugin-可以携带多种能力" tabindex="-1">4.1 一个 Plugin 可以携带多种能力 <a class="header-anchor" href="#_4-1-一个-plugin-可以携带多种能力" aria-label="Permalink to &quot;4.1 一个 Plugin 可以携带多种能力&quot;">​</a></h3><p>Skills、MCP、Hooks、应用连接和资产可以被统一打包，便于团队安装、更新与停用。</p><h3 id="_4-2-安装会扩大信任边界" tabindex="-1">4.2 安装会扩大信任边界 <a class="header-anchor" href="#_4-2-安装会扩大信任边界" aria-label="Permalink to &quot;4.2 安装会扩大信任边界&quot;">​</a></h3><p>管理员和用户需要审查来源、负责人、权限、数据流、版本与撤销方式。安装插件不等于批准其所有连接器动作。</p><h3 id="_4-3-公共能力优先组合而不是复制" tabindex="-1">4.3 公共能力优先组合而不是复制 <a class="header-anchor" href="#_4-3-公共能力优先组合而不是复制" aria-label="Permalink to &quot;4.3 公共能力优先组合而不是复制&quot;">​</a></h3><p>同一流程若在多个插件内复制，会产生版本漂移。稳定基础能力应共享，项目差异放进更靠近仓库的规则或 Skill。</p><p><img src="'+n+'" alt="图 4：Plugin 组合 Skills、MCP、Hooks 与连接能力"></p><h2 id="五、rules-与-hooks-管理动作边界" tabindex="-1">五、Rules 与 Hooks 管理动作边界 <a class="header-anchor" href="#五、rules-与-hooks-管理动作边界" aria-label="Permalink to &quot;五、Rules 与 Hooks 管理动作边界&quot;">​</a></h2><h3 id="_5-1-rules-负责命令策略" tabindex="-1">5.1 Rules 负责命令策略 <a class="header-anchor" href="#_5-1-rules-负责命令策略" aria-label="Permalink to &quot;5.1 Rules 负责命令策略&quot;">​</a></h3><p>规则可以识别允许、需要审批或禁止的命令模式，减少低风险重复确认，同时保留高风险关口。</p><h3 id="_5-2-hooks-负责生命周期检查" tabindex="-1">5.2 Hooks 负责生命周期检查 <a class="header-anchor" href="#_5-2-hooks-负责生命周期检查" aria-label="Permalink to &quot;5.2 Hooks 负责生命周期检查&quot;">​</a></h3><p>Hook 在工具调用、命令执行或会话事件前后运行机械逻辑，适合格式检查、策略校验、日志记录和阻断。</p><h3 id="_5-3-机械执行必须保持简单" tabindex="-1">5.3 机械执行必须保持简单 <a class="header-anchor" href="#_5-3-机械执行必须保持简单" aria-label="Permalink to &quot;5.3 机械执行必须保持简单&quot;">​</a></h3><p>Hook 的输入输出、退出码、超时和失败行为要明确。不要把复杂业务决策塞进难以观察的钩子。</p><p><img src="'+c+'" alt="图 5：Rules、Hooks、Sandbox 与 Approval 构成动作治理链"></p><h2 id="六、subagent-用隔离换取并行" tabindex="-1">六、Subagent 用隔离换取并行 <a class="header-anchor" href="#六、subagent-用隔离换取并行" aria-label="Permalink to &quot;六、Subagent 用隔离换取并行&quot;">​</a></h2><h3 id="_6-1-独立子任务才适合委派" tabindex="-1">6.1 独立子任务才适合委派 <a class="header-anchor" href="#_6-1-独立子任务才适合委派" aria-label="Permalink to &quot;6.1 独立子任务才适合委派&quot;">​</a></h3><p>资料检索、互不重叠模块分析和独立测试调查可以并行。频繁共享状态或修改同一文件的任务更适合顺序执行。</p><h3 id="_6-2-子代理返回证据而不是只报结论" tabindex="-1">6.2 子代理返回证据而不是只报结论 <a class="header-anchor" href="#_6-2-子代理返回证据而不是只报结论" aria-label="Permalink to &quot;6.2 子代理返回证据而不是只报结论&quot;">​</a></h3><p>主线程需要知道读取了哪些来源、得到什么结果、有哪些不确定项。验收责任不能外包给子代理。</p><h3 id="_6-3-并行数量受整合成本限制" tabindex="-1">6.3 并行数量受整合成本限制 <a class="header-anchor" href="#_6-3-并行数量受整合成本限制" aria-label="Permalink to &quot;6.3 并行数量受整合成本限制&quot;">​</a></h3><p>代理越多，协调、冲突和上下文回传成本越高。吞吐提升来自任务可分解，而不是盲目增加执行者。</p><p><img src="'+h+'" alt="图 6：主代理分解目标、子代理隔离执行并返回证据"></p><h2 id="七、建立扩展体系的推荐顺序" tabindex="-1">七、建立扩展体系的推荐顺序 <a class="header-anchor" href="#七、建立扩展体系的推荐顺序" aria-label="Permalink to &quot;七、建立扩展体系的推荐顺序&quot;">​</a></h2><p>先让 Prompt 与 <code>AGENTS.md</code> 稳定单代理工作，再把重复流程提炼为 Skill；确需外部数据时连接最小权限 MCP；需要团队分发时封装 Plugin；需要机械拦截时使用 Rules 和 Hooks；任务真正独立后才增加 Subagent。</p><p><img src="'+p+'" alt="图 7：从规则到 Skill、MCP、Plugin 与多代理的扩展路径"></p><h2 id="八、扩展能力必须可撤销" tabindex="-1">八、扩展能力必须可撤销 <a class="header-anchor" href="#八、扩展能力必须可撤销" aria-label="Permalink to &quot;八、扩展能力必须可撤销&quot;">​</a></h2><p>每项扩展都要有版本、负责人、复查日期和停用方法。外部服务失效、权限扩大或协议变化时，团队应能移除单项能力，而不是让整个 Codex 环境不可用。</p><p><img src="'+d+'" alt="图 8：能力准入、运行观测、复查与撤销闭环"></p><h2 id="九、官方参考资料" tabindex="-1">九、官方参考资料 <a class="header-anchor" href="#九、官方参考资料" aria-label="Permalink to &quot;九、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/customization/overview" target="_blank" rel="noreferrer">OpenAI Docs：Customization</a></p><p><a href="https://learn.chatgpt.com/docs/extend/mcp" target="_blank" rel="noreferrer">OpenAI Docs：MCP</a></p><p><a href="https://learn.chatgpt.com/docs/build-skills" target="_blank" rel="noreferrer">OpenAI Docs：Build skills</a></p><p><a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">OpenAI Docs：Hooks</a></p><p><a href="https://learn.chatgpt.com/docs/agent-configuration/subagents" target="_blank" rel="noreferrer">OpenAI Docs：Subagents</a></p>',63)])])}const S=e(_,[["render",m]]);export{x as __pageData,S as default};
